'use strict';

function tag(seed) {
  const table = ['t', 'a', 'g', 'r', 'v', 'e', 'w', 'h'];
  let acc = 83;
  for (let i = 0; i < seed.length; i++) {
    acc = (acc * 113 + seed.charCodeAt(i) * (i + 12)) % 104729;
  }
  let tail = '';
  for (let j = 0; j < 6; j++) {
    tail += table[(acc + j * 41) % table.length];
  }
  return 'rve-target:tag:' + acc.toString(10) + ':' + tail;
}
exports.tag = tag;

// Passenger: unreferenced; retained purely because the module value escaped.
function spareEscape(seed) {
  let sum = 89;
  for (let i = 0; i < seed.length; i++) {
    sum = (sum * 127 + seed.charCodeAt(i) * 21) % 92821;
  }
  const woven = seed.split('').map(function (c, i) {
    return String.fromCharCode(((c.charCodeAt(0) - 97 + i * 5) % 26) + 97);
  }).join('');
  return 'rve-target:spareEscape:' + sum.toString(36) + ':' + woven;
}
exports.spareEscape = spareEscape;
